const j = $input.item.json;
function parseStr(s){ s=String(s||''); const m=s.match(/<([^>]+)>/); const email=(m?m[1]:s).replace(/^["']|["']$/g,'').trim(); const name=s.replace(/<[^>]+>/,'').replace(/["']/g,'').trim()||email; return {email,name}; }
// Gmail nodes return From/To in several shapes across versions (string, {value:[{address,name}]}, {address}, payload.headers). This handles all of them.
function addr(x){ if(!x) return {email:'',name:''}; if(typeof x==='string') return parseStr(x); if(Array.isArray(x)) return x[0]?{email:x[0].address||'',name:x[0].name||x[0].address||''}:{email:'',name:''}; if(Array.isArray(x.value)&&x.value[0]) return {email:x.value[0].address||'',name:x.value[0].name||x.value[0].address||''}; if(x.address) return {email:x.address,name:x.name||x.address}; if(x.text) return parseStr(x.text); return {email:'',name:''}; }
const F=addr(j.From||j.from);
const fromEmail=F.email; const fromName=F.name||fromEmail;
const subject=String(j.Subject||j.subject||'(no subject)');
const body=String(j.text||j.textPlain||j.snippet||j.html||'').replace(/<[^>]+>/g,' ').slice(0,6000);
const threadId=j.threadId||(j.payload&&j.payload.threadId)||'';
// EDIT this noise list for your inbox:
const noiseRe=/(no-?reply|noreply|donotreply|do-not-reply|notifications?|mailer-daemon|postmaster|newsletter|automated|bounce|mailchimp|klaviyo)/i;
return [{ json:{ fromEmail, fromName, subject, body, threadId, prefilterNoise:noiseRe.test(fromEmail) } }];

const e=$json; const system="You are an email triage classifier for {{BRAND_NAME}} ({{ONE_LINE_DESCRIPTION}}). Classify the single inbound email. Return ONLY minified JSON, no prose, with exactly these keys:
segment: one of ["customer","reseller_b2b","investor","ops_logistics","press","noise"]   // EDIT this list to match your business
intent: one of ["order_status","product_question","return_refund","wholesale_enquiry","complaint","billing","investor","press","general"]   // EDIT
priority: "P1" (hot / time-sensitive), "P2" (needs care), "P3" (routine), "P4" (low)
sentiment: one of ["positive","neutral","frustrated","at_risk"]
is_noise: true for automated notifications, receipts, newsletters, cold sales pitches, or self-sent mail
needs_order_lookup: true only if a customer is asking about a specific existing order, return, or tracking
customer_email: the sender's email address if needs_order_lookup is true, else ""
// EDIT: describe each segment/intent for your brand, and add routing rules (e.g. investor => segment "investor").";
const user=`From: ${e.fromName} <${e.fromEmail}>
Subject: ${e.subject}

${e.body}`;
// Haiku = cheap classifier. Swap model string for your provider/model if needed.
return [{ json:{ anthropicBody:{ model:'claude-haiku-4-5-20251001', max_tokens:400, system, messages:[{role:'user',content:user}] } } }];

// Claude may return a 'thinking' block before the 'text' block — never assume content[0]. Find the text block.
const blocks = Array.isArray($json.content) ? $json.content : [];
let t = (blocks.find(b => b && b.type === 'text') || {}).text || '{}';
t = t.replace(/```json/gi,'').replace(/```/g,'').trim();
let c; try{c=JSON.parse(t);}catch(e){c={segment:'customer',intent:'general',priority:'P2',sentiment:'neutral',is_noise:false,needs_order_lookup:false,customer_email:''};}
return [{ json:c }];

const items=$input.all().map(i=>i.json); let msgs=[];
if(items.length===1&&Array.isArray(items[0].messages))msgs=items[0].messages; else msgs=items;
function parseStr(s){ s=String(s||''); const m=s.match(/<([^>]+)>/); return (m?m[1]:s).trim(); }
function who(m){ const x=m.From||m.from; if(!x)return ''; if(typeof x==='string')return parseStr(x); if(Array.isArray(x.value)&&x.value[0])return x.value[0].name||x.value[0].address||''; if(x.address)return x.name||x.address; if(x.text)return parseStr(x.text); if(m.headers&&m.headers.from)return parseStr(m.headers.from); const H=(m.payload&&m.payload.headers)||[]; const f=H.find(h=>h.name&&h.name.toLowerCase()==='from'); return f?parseStr(f.value):''; }
const rows=msgs.map(m=>{ const from=who(m); const date=m.date||m.internalDate||''; const text=String(m.snippet||m.text||'').replace(/\s+/g,' ').slice(0,300); return `${date} | ${from}: ${text}`; }).filter(r=>r.replace(/[^a-z0-9]/gi,'').length>3);
const threadHistory = rows.slice(-8).join('\n') || 'No prior messages in this thread (first contact).';
return [{ json:{ ...$('Parse Classification').item.json, threadHistory } }];

const rows=$input.all().map(i=>i.json);
const get=k=>{ const r=rows.find(r=>String(r.key||'').trim()===k); return r?String(r.value||'').trim():''; };
const opsManual=get('manual_status')||'(none set)';
const opsAuto=get('auto_facts')||'No current operational notes.';
return [{ json:{ ...$('Summarise Thread History').item.json, opsManual, opsAuto } }];

// EDIT: adapt to your store's order shape (this example matches WooCommerce).
const orders=$input.all().map(i=>i.json).filter(o=>o&&(o.id||o.number)); let ctx;
if(orders.length){ const o=orders[0]; const items=(o.line_items||[]).map(li=>`${li.quantity}x ${li.name}`).join(', '); ctx=`Most recent order #${o.number||o.id}: status=${o.status}, placed=${o.date_created}, total=${o.currency||''}${o.total}, items=[${items}].`; }
else { ctx='No matching order found — the draft must politely ask for the order number rather than guessing.'; }
return [{ json:{ orderContext:ctx } }];

const e=$('Prepare Email').item.json;
const c=$('Parse Classification').item.json;
const th=$('Summarise Thread History').item.json.threadHistory||'No prior messages.';
const of=$('Compose Ops Facts').item.json;
const orderContext=$json.orderContext||'';
const system="You draft an email reply AS {{BRAND_NAME}}. Voice: {{VOICE_GUIDELINES — e.g. warm, plain-language, human; no corporate stiffness; no emoji unless they used one}}. Lead with the person's situation, not features. Short and human.

CURRENT-STATUS PRIORITY (most authoritative first) — this is the reusable pattern, keep it:
1) MANUAL STATUS — facts a human set by hand (stock, promos, delays). Ground truth. Never contradict it.
2) THIS THREAD'S HISTORY — what we already told THIS person. Stay consistent.
3) RECENT OPERATIONAL NOTES — auto-detected from our recent sent mail (what we told OTHER people this week). Use to stay consistent, but if a reply depends on one of these, set needs_founder_input=true so a human confirms.
Newer information always beats older. Never contradict MANUAL STATUS.

GUARDRAILS (hard) — EDIT for your brand:
- Only state facts from BRAND CONTEXT, MANUAL STATUS, RECENT OPERATIONAL NOTES, ORDER CONTEXT, or THREAD HISTORY. If you lack a fact, do NOT invent it — say you'll confirm, or ask.
- Never invent an order number, tracking, ship date, price, or quantities.
- For {{SENSITIVE_TOPICS — e.g. pricing, discounts, contracts}}: set needs_founder_input=true.
- {{ADD YOUR OWN NON-NEGOTIABLES — restricted words, competitor policy, regulated claims, escalation rules}}.

=== BRAND CONTEXT (REPLACE THIS ENTIRE BLOCK with your own customer-safe facts. Never put confidential data here — it can surface in a reply.) ===
ABOUT: {{WHAT YOUR BUSINESS DOES, tagline, website}}
PRODUCTS/SERVICES: {{KEY FACTS a reply may need}}
PRICING: {{PUBLIC PRICING ONLY. Keep confidential/wholesale pricing out, or gate it behind needs_founder_input}}
POLICIES: Shipping: {{...}} | Returns: {{...}} | Warranty: {{...}}
{{OPTIONAL: paste your FAQ Q&As here, or add a node that fetches them}}
=== END BRAND CONTEXT ===

Return ONLY minified JSON: {"subject":"...","body":"...","needs_founder_input":true|false,"medical_flag":false}. "body" is plain text with real line breaks, signed off warmly.
Reply with ONLY the minified JSON described above — no other text.";
const user=`SEGMENT: ${c.segment} | INTENT: ${c.intent} | PRIORITY: ${c.priority} | SENTIMENT: ${c.sentiment}

MANUAL STATUS (authoritative): ${of.opsManual}

RECENT OPERATIONAL NOTES: ${of.opsAuto}

ORDER CONTEXT: ${orderContext||'none'}

THIS THREAD HISTORY (oldest first, latest last):
${th}

NEW INBOUND EMAIL TO REPLY TO
From: ${e.fromName} <${e.fromEmail}>
Subject: ${e.subject}

${e.body}`;
// Sonnet = quality writer, only reached for genuine actionable mail.
return [{ json:{ anthropicBody:{ model:'claude-sonnet-5', max_tokens:1500, system, messages:[{role:'user',content:user}] }, replyTo:e.fromEmail, threadId:e.threadId, inSubject:e.subject, priority:c.priority } }];

const blocks = Array.isArray($json.content) ? $json.content : [];
let t = (blocks.find(b => b && b.type === 'text') || {}).text || '{}';
t = t.replace(/```json/gi,'').replace(/```/g,'').trim();
const bd=$('Build Draft Request').item.json; let d; try{d=JSON.parse(t);}catch(e){d={subject:'Re: '+(bd.inSubject||''),body:t,needs_founder_input:true};}
let body=d.body||''; if(d.needs_founder_input)body='[HUMAN REVIEW NEEDED BEFORE SENDING]\n\n'+body;
return [{ json:{ to:bd.replyTo, threadId:bd.threadId, subject:d.subject||('Re: '+(bd.inSubject||'')), body, priority:bd.priority } }];

const labels=$input.all().map(i=>i.json).filter(l=>l&&l.name&&l.id); const map={}; for(const l of labels)map[l.name]=l.id;
const c=$('Parse Classification').item.json; const threadId=$('Prepare Email').item.json.threadId;
// EDIT: map each segment to a Gmail label you have created (create these labels first).
const segMap={ customer:'AI/Customer', reseller_b2b:'AI/B2B', investor:'AI/Investor', ops_logistics:'AI/Ops' };
const wanted=[ segMap[c.segment], 'AI/'+(c.priority||'') ].filter(Boolean);
const labelIds=wanted.map(n=>map[n]).filter(Boolean);
if(!labelIds.length||!threadId)return []; return [{ json:{ threadId, labelIds } }];
